# 12_verificacao.R - checklist OK/FALTA de requisitos do P2 (rodar apos run_all.R)
source("R/00_config.R")
ck <- list()
add <- function(req, ok, det = "") ck[[length(ck) + 1]] <<- data.frame(requisito = req, status = ifelse(isTRUE(ok), "OK", "FALTA"), detalhe = det)
ex <- function(f) file.exists(f)
b <- read.csv(file.path(DIR$dados, "base_intangivel_2025.csv.gz")); g <- read.csv(file.path(DIR$dados, "gabarito_base_limpa.csv.gz"))
pts <- read.csv(file.path(DIR$res, "pts_27.csv"), stringsAsFactors = FALSE)
add("Base com pelo menos 500.000 registros", nrow(b) >= 500000, paste(nrow(b), "registros"))
add("Base limpa reconcilia ao Intangivel da DFP (31.729.991 mil)", abs(sum(g$valor_liquido_mil) - 31729991) < 0.001, fmt(sum(g$valor_liquido_mil), 3))
add("Dicionario de dados e premissas", ex("dados/dicionario_dados.csv") && ex("dados/premissas_base.csv"))
add("Log de erros inseridos (gabarito)", ex("dados/log_erros_inseridos.csv"))
add("Comparacao inserido x detectado", ex("resultados/07_inserido_vs_detectado_por_tipo.csv") && ex("resultados/08_inserido_vs_detectado_resumo.csv"))
add("Erros nao detectados investigados", ex("resultados/09_erros_nao_detectados.csv"))
add("Reconciliacoes (base x Nota 14; BP x Notas 14/14.1/16)", ex("resultados/10_conciliacao_base_x_nota14.csv") && ex("resultados/12_conciliacao_dfp_notas.csv"))
add("Materialidade: benchmarks, adotada e justificativa", ex("resultados/01_materialidade_benchmarks.csv") && ex("resultados/02_materialidade_adotada.csv") && ex("resultados/04_materialidade_justificativa.txt"))
add("MUS: parametros, amostra e avaliacao Stringer (pre e pos)", all(ex(file.path(DIR$res, c("14_mus_parametros_original.csv","15_mus_amostra_selecionada_original.csv","16_mus_avaliacao_stringer_original.csv","16_mus_avaliacao_stringer_pos_correcao.csv")))))
add("Sensibilidade executada (WACC x g, um fator, vida util)", all(ex(file.path(DIR$res, c("18_sensibilidade_wacc_g.csv","19_sensibilidade_um_fator.csv","20_sensibilidade_vida_util.csv")))))
add("Procedimentos analiticos (PT 520)", ex("resultados/21_analitico_amortizacao.csv") && ex("resultados/22_analitico_indices.csv"))
add("27 papeis de trabalho", nrow(pts) == 27, paste(nrow(pts)))
campos <- c("codigo","titulo","norma_itens","objetivo","conta_processo_divulgacao","afirmacoes","riscos","populacao_fontes_criterios","procedimentos","evidencias_referencias","resultados","excecoes","conclusao","limitacoes","natureza","preparador","data_elaboracao","revisao")
add("Estrutura minima uniforme em todos os PTs", all(campos %in% names(pts)) && !any(sapply(pts[campos], function(x) any(!nzchar(trimws(x))))))
add("Natureza com as tres classes oficiais", all(pts$natureza %in% c("Realizado com evidência pública","Planejado por falta de acesso","Simulado para fins didáticos")))
add("Preparador por matricula e campo de revisao", all(grepl(MATRICULA, pts$preparador)) && all(grepl("PENDENTE", pts$revisao)))
add("Nenhum 'nao se aplica' sem justificativa", !any(grepl("^n(ã|a)o se aplica\\.?$", tolower(trimws(unlist(pts[campos]))))))
add("Arquivo .md por PT", all(ex(file.path(DIR$pt, paste0(gsub(" ", "_", pts$codigo), ".md")))))
add("Seis programas de auditoria", length(list.files(DIR$prog, "\\.md$")) == 6)
add("Minutas e modelos (contratacao, governanca, circularizacao, representacao, recomendacoes, relatorio didatico)", length(list.files(DIR$min, "\\.md$")) == 6)
roteiro <- c("PT EC", paste("PT", c(200,210,220,230,240,250,260,265,300,315,320,330,402,450,500,501,505,510,520,530,540,550,560,570,580,600)))
add("Codigos dos PTs identicos ao roteiro do P2 (PT EC + 26 NBC TA)", setequal(pts$codigo, roteiro) && length(roteiro) == 27)
add("Matrizes do roteiro (riscos, respostas, distorcoes, deficiencias, evidencias)", all(ex(file.path(DIR$res, c("23_matriz_riscos.csv","24_matriz_respostas_riscos.csv","25_mapa_distorcoes.csv","26_matriz_deficiencias.csv","27_avaliacao_evidencias.csv")))))
add("Fontes com endereco, data de acesso, documento, pagina e exercicio", all(c("endereco_eletronico","data_acesso","documento","pagina","exercicio") %in% names(read.csv("fontes/controle_fontes.csv"))))
add("Versao da norma registrada para cada PT", ex("resultados/matriz_cobertura_nbc_ta.csv") && !any(is.na(read.csv("resultados/matriz_cobertura_nbc_ta.csv")$versao_norma)))
add("Conclusao integrada, indice e convencao de codigos", all(ex(c("docs/conclusao_integrada.md","docs/indice_pts.md","docs/convencao_codigos.md"))))
add("Base marcada como SINTETICA", "origem_dado" %in% names(b) && all(b$origem_dado == "SINTETICO"))
add("Nenhum PT afirma opiniao propria ('em nossa opiniao')", !any(grepl("em nossa opini", tolower(unlist(pts)))) && !any(grepl("em nossa opini", tolower(unlist(lapply(list.files(DIR$min, full.names = TRUE), readLines, encoding = "UTF-8"))))))
add("Matriz de cobertura NBC TA e fontes", ex("resultados/matriz_cobertura_nbc_ta.csv") && ex("fontes/controle_fontes.csv") && ex("fontes/fatos_dfp_2025.csv"))
add("Dossie (md/html/pdf)", ex("dossie/dossie_P2.md") && ex("dossie/dossie_P2.html") && ex("dossie/dossie_P2.pdf"))
add("Pendencias registradas", ex("resultados/pendencias.csv"))
r <- do.call(rbind, ck); write.csv(r, file.path(DIR$res, "verificacao.csv"), row.names = FALSE, fileEncoding = "UTF-8")
print(r, right = FALSE); cat("\n", sum(r$status == "OK"), "de", nrow(r), "requisitos OK\n")
